import{_ as l,a0 as u,w as r,s,ao as p,I as e,x as t,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Linux Journal 停止發行 | LCTT x X-CMD","titleTemplate":false,"description":"Linux Journal 停止發行 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Journal 停止發行 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Journal 停止發行 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171201 Linux Journal Ceases Publication","title":"Linux Journal 停止發行","tag":"201712","desc":""},"relativePath":"201712/20171201 Linux Journal Ceases Publication.md","filePath":"[post].md"}'),x={name:"201712/20171201 Linux Journal Ceases Publication.md"};function d(L,n,m,f,T,C){const a=u("Link");return r(),s("div",null,[n[13]||(n[13]=p('<h1 id="linux-journal-停止發行" tabindex="-1">Linux Journal 停止發行 <a class="header-anchor" href="#linux-journal-停止發行" aria-label="Permalink to “Linux Journal 停止發行”">​</a></h1><p>EOF</p><p>夥計們，看起來我們要到終點了。如果按照計劃而且沒有什麼其他的話，十一月份的 Linux Journal 將是我們的最後一期。</p><p>簡單的事實是，我們已經用完了錢和期權。我們從來沒有一個富有的母公司或者自己深厚的資金，從開始到結束，這使得我們變成一個反常的出版商。雖然我們在很長的一段時間內運營着，但當天平不可恢復地最終向相反方向傾斜時，我們在十一月份失去了最後一點支持。</p><p>雖然我們像看到出版業的過去那樣看到出版業的未來 - 廣告商贊助出版物的時代，因為他們重視品牌和讀者 - 我們如今的廣告寧願追逐眼球，最好是在讀者的瀏覽器中植入跟蹤標記，並隨時隨地展示那些廣告。但是，未來不是這樣，過去的已經過去了。</p><p>我們猜想，有一個希望，那就是救世主可能會會來。但除了我們的品牌、我們的檔案，我們的域名、我們的用户和讀者之外，還必須是願意承擔我們一部分債務的人。如果你認識任何人能夠提供認真的報價，請告訴我們。不然，請觀看 LinuxJournal.com，並希望至少我們的遺留歸檔（可以追溯到 Linux Journal 誕生的 1994 年 4 月，當 Linux 命中 1.0 發佈時）將不會消失。這裏有很多很棒的東西，還有很多我們會痛恨世界失去的歷史。</p><p>我們最大的遺憾是，我們甚至沒有足夠的錢回饋最看重我們的人：我們的用户。為此，我們不能更深刻或真誠地道歉。我們對訂閲者而言有什麼：</p><p>Linux Pro Magazine 為我們的用户提供了六本免費的雜誌，我們在 Linux Journal 上一直讚歎這點。在我們需要的時候，他們是我們的第一批人，我們感謝他們的恩惠。我們今天剛剛完成了我們的 2017 年歸檔，其中包括我們曾經發表過的每一個問題，包括第一個和最後一個。通常我們以 25 美元的價格出售，但顯然用户將免費獲得。訂閲者請注意有關兩者的詳細信息的電子郵件。</p><p>我們也希望在知道我們非常非常努力地讓 Linux Journal 進行下去後能有一些安慰 ，而且我們已經用最精益、小的可能運營了很長一段時間。我們是一個大多數是自願者的組織，有些員工已經幾個月沒有收到工資。我們還欠錢給自由職業者。這時一個限制發行商能夠維持多長時間的限制，現在這個限制已經到頭了。</p><p>夥計們，這是一個偉大的運營。鄉親。對每一個為我們的誕生、我們的成功和我們多年的堅持作出貢獻的人致敬。我們列了一份名單，但是列表太長了，並且漏掉有價值的人的風險很高。你知道你是誰。我們再次感謝。</p><hr>',11)),e("p",null,[n[1]||(n[1]=t("via: ",-1)),i(a,{href:"https://www.linuxjournal.com/content/linux-journal-ceases-publication"},{default:o(()=>[...n[0]||(n[0]=[t("https://www.linuxjournal.com/content/linux-journal-ceases-publication",-1)])]),_:1})]),e("p",null,[n[5]||(n[5]=t("作者：",-1)),i(a,{href:"https://www.linuxjournal.com/users/carlie-fairchild"},{default:o(()=>[...n[2]||(n[2]=[t(" Carlie Fairchild",-1)])]),_:1}),n[6]||(n[6]=t(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:o(()=>[...n[3]||(n[3]=[t("geekpi",-1)])]),_:1}),n[7]||(n[7]=t(" 校對：",-1)),i(a,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:o(()=>[...n[4]||(n[4]=[t("校對者ID",-1)])]),_:1})]),e("p",null,[n[10]||(n[10]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[8]||(n[8]=[t("LCTT",-1)])]),_:1}),n[11]||(n[11]=t(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:o(()=>[...n[9]||(n[9]=[t("Linux中國",-1)])]),_:1}),n[12]||(n[12]=t(" 榮譽推出",-1))])])}const w=l(x,[["render",d]]);export{g as __pageData,w as default};
